import{_ as a,C as i,o as n,c as s,j as t,a as r,E as d,a2 as h}from"./chunks/framework.DdtnLau3.js";const P=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Piwork","text":"可分享、可运行的 AI 工作空间","tagline":"由可演进的 Harness 驱动。","image":{"src":"/logo.png","alt":"Piwork"},"actions":[{"theme":"brand","text":"开始使用","link":"/zh/guide/quick-start"},{"theme":"alt","text":"观看演示","link":"/zh/demo/product-demo.html"},{"theme":"alt","text":"GitHub","link":"https://github.com/pphboy/piwork"},{"theme":"alt","text":"讨论社区","link":"https://github.com/pphboy/piwork/discussions"}]}},"headers":[],"relativePath":"zh/index.md","filePath":"zh/index.md"}'),l={name:"zh/index.md"};function p(k,e,c,m,b,u){const o=i("ProductDemo");return n(),s("div",null,[e[0]||(e[0]=t("h2",{id:"_70-秒了解-piwork",tabindex:"-1"},[r("70 秒了解 Piwork "),t("a",{class:"header-anchor",href:"#_70-秒了解-piwork","aria-label":'Permalink to "70 秒了解 Piwork"'},"​")],-1)),e[1]||(e[1]=t("p",null,[r("AI 创建真实的内容工作室，在保留已有灵感的基础上持续进化，再将整个 Work 迁移到另一套 Piwork 环境。"),t("a",{href:"/piwork/zh/demo/product-demo.html"},"查看演示与录制说明"),r("。")],-1)),d(o),e[2]||(e[2]=h('<h2 id="piwork-是什么" tabindex="-1">Piwork 是什么？ <a class="header-anchor" href="#piwork-是什么" aria-label="Permalink to &quot;Piwork 是什么？&quot;">​</a></h2><p>Piwork 将可运行的 AI 工作空间封装成一个可携带的单元，称为 <strong>Work</strong>。应用、文件、对话历史和执行环境保存在一起；导出后，可以在另一个 Piwork 实例中继续使用。</p><table tabindex="0"><thead><tr><th>概念</th><th>职责</th></tr></thead><tbody><tr><td><a href="/piwork/zh/concepts/work.html">Work</a></td><td><strong>工作空间。</strong> 保存环境和持久状态。</td></tr><tr><td><a href="/piwork/zh/concepts/service.html">Service</a></td><td><strong>能力。</strong> 运行应用、API 或其他容器服务。</td></tr><tr><td><a href="/piwork/zh/concepts/harness.html">Harness</a></td><td><strong>智能层。</strong> 通过模型、工具和工作空间专属指令理解并操作 Work。</td></tr></tbody></table><p>Harness 可以帮助构建和修改它所在的工作空间。它的指令、Skills、扩展包和经过验证的经验，可以随着 Work 一起演进。</p><p>默认 Web 开发使用可复用的 Python + NiceGUI + SQLite 环境。标准模板自动采用已部署的更新；使用与维护入口见 <a href="/piwork/zh/guide/web-development.html">Web 开发</a>。</p><h2 id="如何使用" tabindex="-1">如何使用 <a class="header-anchor" href="#如何使用" aria-label="Permalink to &quot;如何使用&quot;">​</a></h2><p><strong>创建 → 运行 → 演进 → 导出 → 分享 → 导入 → 继续</strong></p><p>将已停止的 Work 导出为 <code>.work</code> 文件，在兼容的实例中导入，再手动启动。接收方需要配置自己的模型凭据。</p><h2 id="示例-kanban-work" tabindex="-1">示例：Kanban Work <a class="header-anchor" href="#示例-kanban-work" aria-label="Permalink to &quot;示例：Kanban Work&quot;">​</a></h2><p>看板、数据、应用 Service 和帮助构建及操作看板的 Harness，共同组成一个工作空间。<a href="/piwork/zh/demo/kanban.html">查看 Kanban 演示说明</a>。该看板示例的可下载演示包和录屏仍在准备中。</p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h2><p><a href="/piwork/zh/guide/quick-start.html">一键启动 Piwork</a>：一个 Docker 容器，打开服务器 IP 的网页完成管理员、模型与 CoreRuntime 配置，直接使用完整工作台。无需 CLI、域名或初始化环境。可选 <a href="/piwork/piwork/install/0.0.9-0901cf119dc1-0e1261f05b9d/docker-compose.yml">docker-compose.yml</a>。当前状态 published；镜像已发布并完成匿名核验。</p>',12))])}const f=a(l,[["render",p]]);export{P as __pageData,f as default};
